use std::collections::VecDeque;impl Solution{pub fn alien_order(w:Vec<String>)->String{let mut g=vec![vec![];26];let mut d=vec![0;26];let mut s=vec![false;26];for x in &w{for b in x.bytes(){s[(b-b'a')as usize]=true}}for i in 0..w.len()-1{let(a,b)=(w[i].as_bytes(),w[i+1].as_bytes());let mut j=0;while j<a.len().min(b.len())&&a[j]==b[j]{j+=1}if j==a.len().min(b.len()){if a.len()>b.len(){return String::new()}}else{let x=(a[j]-b'a')as usize;let y=(b[j]-b'a')as usize;if !g[x].contains(&y){g[x].push(y);d[y]+=1;}}}let mut q=VecDeque::new();let mut cnt=0;for i in 0..26{if s[i]{cnt+=1;if d[i]==0{q.push_back(i)}}}let mut r=String::new();while let Some(u)=q.pop_front(){r.push((b'a'+u as u8)as char);for &v in &g[u]{d[v]-=1;if d[v]==0{q.push_back(v)}}}if r.len()==cnt{r}else{String::new()}}}
